// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"Businesses turn inputs into goods and services. Unit 1 asks what businesses are and what they aim for.","blocks":[{"t":"key","text":"Sectors: primary (extraction), secondary (manufacturing), tertiary (services) and quaternary (knowledge). Legal forms: sole traders and partnerships (unlimited liability), privately and publicly held companies (limited liability), and for-profit social enterprises and non-profits."},{"t":"p","text":"Objectives: vision and mission statements, aims, objectives, strategies and tactics. Corporate social responsibility (CSR) considers ethics and sustainability. Tools: SWOT analysis and STEEPLE analysis."},{"t":"p","text":"Stakeholders are internal (employees, managers, shareholders) and external (customers, suppliers, government, community); their interests can conflict. Growth can be internal (organic) or external (mergers, takeovers, joint ventures, franchising)."}]},{"say":"People are a business's most important resource. Unit 2 covers how they're organized, motivated and led.","blocks":[{"t":"key","text":"Workforce planning, recruitment (internal or external), training and appraisal. Organizational structures: hierarchy, span of control, delegation, flat versus tall structures, and centralization."},{"t":"p","text":"Leadership styles: autocratic, paternalistic, democratic and laissez-faire. Motivation theories: Taylor (financial incentives), Maslow (hierarchy of needs), Herzberg (hygiene factors and motivators), and others; financial rewards (salary, commission, profit-related pay) and non-financial rewards (job enrichment, empowerment, teamwork)."},{"t":"p","text":"Organizational culture shapes behaviour; industrial relations involve unions, collective bargaining and conflict resolution."}]}],[{"say":"Finance tells a business whether it can survive. Break-even analysis is a core tool.","blocks":[{"t":"key","text":"Sources of finance: internal (retained profit, sale of assets) and external (share capital, loans, overdrafts, leasing, crowdfunding, microfinance)."},{"t":"p","text":"Costs are fixed (rent) or variable (materials). Total cost = fixed cost + variable cost. Contribution per unit = price − variable cost per unit."},{"t":"p","text":"Break-even quantity = fixed costs ÷ contribution per unit. The margin of safety is actual output minus break-even output. Target profit output = (fixed costs + target profit) ÷ contribution per unit."},{"t":"ex","problem":"Fixed costs are $12,000, price is $20 and variable cost is $14 per unit. Find the break-even quantity.","steps":["Contribution = 20 − 14 = $6","12,000 ÷ 6"],"answer":"2,000 units"}]},{"say":"Accounts show performance and position. Ratios let you compare them over time and against rivals.","blocks":[{"t":"key","text":"The statement of profit or loss shows revenue, cost of sales, gross profit, expenses and profit. The statement of financial position shows assets, liabilities and equity. Depreciation spreads an asset's cost over its life (straight-line method)."},{"t":"p","text":"Profitability ratios: gross profit margin = gross profit ÷ revenue × 100; profit margin = profit before interest and tax ÷ revenue × 100. Liquidity: current ratio = current assets ÷ current liabilities (about 1.5–2 is healthy); acid-test excludes inventory."},{"t":"p","text":"Cash flow differs from profit: a profitable firm can still fail from poor cash flow. Cash-flow forecasts plan inflows and outflows."},{"t":"ex","problem":"Revenue is $200,000 and gross profit is $80,000. Find the gross profit margin.","steps":["80,000 ÷ 200,000 × 100"],"answer":"40%"}]}],[{"say":"Marketing identifies and satisfies customer needs profitably.","blocks":[{"t":"key","text":"Market orientation versus product orientation. Market segmentation, targeting and positioning (with position maps). Market research: primary (surveys, interviews) and secondary (reports); sampling methods."},{"t":"p","text":"The marketing mix: product (product life cycle, Boston Consulting Group matrix), price (cost-plus, penetration, skimming, psychological, competitive), promotion (above and below the line, social media), and place (distribution channels). Services add people, processes and physical evidence (7 Ps)."},{"t":"p","text":"Branding and the unique selling point (USP) differentiate a product."}]},{"say":"Operations turn inputs into outputs efficiently, sustainably and with good quality.","blocks":[{"t":"key","text":"Production methods: job, batch, flow (mass) and cellular. Lean production reduces waste through just-in-time (JIT) stock control and kaizen (continuous improvement)."},{"t":"p","text":"Quality: quality control inspects outputs; quality assurance builds quality into processes; total quality management (TQM) involves everyone. Benchmarking compares with best practice."},{"t":"p","text":"Location decisions weigh costs, infrastructure and markets. Supply chain management, outsourcing, offshoring and reshoring. Research and development and innovation (product and process) drive growth; crisis management and contingency planning prepare for disruption."}]}]];
export default text;
